type Stat = {
  label: string
  value: string | number
}

type Props = {
  stats: Stat[]
  className?: string
}

export function StatBar({ stats, className }: Props) {
  return (
    <div className={`flex items-center divide-x divide-border bg-card rounded-lg border border-border px-1 ${className ?? ''}`}>
      {stats.map((stat, i) => (
        <div key={i} className="flex flex-col items-center px-5 py-3">
          <span className="text-xl font-bold text-foreground leading-tight">{stat.value}</span>
          <span className="text-xs text-muted-foreground mt-0.5">{stat.label}</span>
        </div>
      ))}
    </div>
  )
}
